import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target_positions = inputs["target_positions"].copy()
    position_events = inputs["position_events"].copy()

    # --- Normalize types defensively ---
    if len(target_positions) > 0:
        target_positions["account_id"] = target_positions["account_id"].astype("int64")
        target_positions["symbol"] = target_positions["symbol"].astype(str)
        target_positions["row_version"] = target_positions["row_version"].astype("int64")

    if len(position_events) > 0:
        position_events["account_id"] = position_events["account_id"].astype("int64")
        position_events["symbol"] = position_events["symbol"].astype(str)
        position_events["row_version"] = position_events["row_version"].astype("int64")
        position_events["batch_seq"] = position_events["batch_seq"].astype("int64")
        position_events["op"] = position_events["op"].astype(str).str.strip().str.upper()

    # --- Build initial state from target_positions ---
    # Defensive: if duplicate keys somehow exist in target_positions, keep the
    # row with the highest row_version (ties broken by original row order) as
    # authoritative, since row_version denotes "version that last wrote the row".
    state = {}
    target_version = {}

    if len(target_positions) > 0:
        tp = target_positions.reset_index(drop=False)
        tp = tp.sort_values(by=["row_version", "index"], kind="mergesort")
        for _, row in tp.iterrows():
            key = (row["account_id"], row["symbol"])
            state[key] = {
                "qty": row["qty"],
                "price": row["price"],
                "row_version": row["row_version"],
            }
            target_version[key] = row["row_version"]

    # --- Step 1: dedup events by batch_seq (same event delivered more than once) ---
    if len(position_events) > 0:
        events = position_events.drop_duplicates(subset=["batch_seq"], keep="first").copy()
    else:
        events = position_events.copy()

    # --- Step 2: replay guard ---
    if len(events) > 0:
        tv_account = events["account_id"]
        tv_symbol = events["symbol"]
        keys = list(zip(tv_account, tv_symbol))
        guard_vals = [target_version.get(k, None) for k in keys]
        guard_series = pd.Series(guard_vals, index=events.index)

        mask = guard_series.isna() | (events["row_version"] > guard_series)
        events = events[mask]

    # --- Step 3: order remaining events by row_version, batch_seq ---
    if len(events) > 0:
        events = events.sort_values(by=["row_version", "batch_seq"], kind="mergesort")

    # track last-applied-event removal status per key
    last_removed_version = {}  # key -> row_version if last event removed existing row
    last_event_seen = set()

    for _, ev in events.iterrows():
        key = (ev["account_id"], ev["symbol"])
        op = ev["op"]
        ev_qty = ev["qty"]
        ev_price = ev["price"]
        rv = ev["row_version"]

        current = state.get(key, None)
        acted_remove = False

        if op == "D":
            if current is not None:
                state[key] = None
                acted_remove = True
            else:
                acted_remove = False
        elif op in ("I", "U"):
            is_zero = (not pd.isna(ev_qty)) and (ev_qty == 0)
            if is_zero:
                if current is not None:
                    state[key] = None
                    acted_remove = True
                else:
                    acted_remove = False
            else:
                if current is not None:
                    new_price = ev_price
                    if op == "U" and pd.isna(ev_price):
                        new_price = current["price"]
                    state[key] = {
                        "qty": ev_qty,
                        "price": new_price,
                        "row_version": rv,
                    }
                else:
                    state[key] = {
                        "qty": ev_qty,
                        "price": ev_price,
                        "row_version": rv,
                    }
                acted_remove = False
        else:
            # unknown op, ignore
            acted_remove = False

        # update "last applied event" closing status for this key
        if acted_remove:
            last_removed_version[key] = rv
        else:
            last_removed_version[key] = None
        last_event_seen.add(key)

    # --- Step 4: build new_positions ---
    new_rows = []
    for key, val in state.items():
        if val is not None:
            account_id, symbol = key
            qty_val = val["qty"]
            if pd.isna(qty_val):
                qty_out = qty_val
            else:
                qty_out = int(qty_val)
            new_rows.append({
                "account_id": account_id,
                "symbol": symbol,
                "qty": qty_out,
                "price": val["price"],
                "row_version": val["row_version"],
            })

    new_positions = pd.DataFrame(
        new_rows, columns=["account_id", "symbol", "qty", "price", "row_version"]
    )
    new_positions["account_id"] = new_positions["account_id"].astype("int64")
    if len(new_positions) > 0:
        new_positions["qty"] = new_positions["qty"].astype("int64")
    else:
        new_positions["qty"] = new_positions["qty"].astype("int64")
    new_positions["price"] = new_positions["price"].astype("float64")
    new_positions["row_version"] = new_positions["row_version"].astype("int64")

    if len(new_positions) > 0:
        new_positions = new_positions.sort_values(
            by=["account_id", "symbol"], kind="mergesort"
        ).reset_index(drop=True)

    # --- Step 5: build closed_positions ---
    closed_rows = []
    for key in last_event_seen:
        rv = last_removed_version.get(key)
        if rv is not None:
            account_id, symbol = key
            closed_rows.append({
                "account_id": account_id,
                "symbol": symbol,
                "closed_version": rv,
            })

    closed_positions = pd.DataFrame(
        closed_rows, columns=["account_id", "symbol", "closed_version"]
    )
    closed_positions["account_id"] = closed_positions["account_id"].astype("int64")
    closed_positions["closed_version"] = closed_positions["closed_version"].astype("int64")

    if len(closed_positions) > 0:
        closed_positions = closed_positions.sort_values(
            by=["account_id", "symbol"], kind="mergesort"
        ).reset_index(drop=True)

    return {
        "new_positions": new_positions,
        "closed_positions": closed_positions,
    }
